    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '101: Which of the following ECG changes is the earliest sign of acute myocardial infarction (often seen within minutes)?', '["Pathological Q-waves", "T-wave inversion", "Hyperacute (tall, symmetric) T-waves", "ST-segment depression"]', 2, 'Hyperacute T-waves are the earliest change, followed quickly by ST-segment elevation.'),
    (v_topic_id, '102: To diagnose an ST-Elevation Myocardial Infarction (STEMI), how much elevation is generally required in at least two contiguous leads (excluding V2-V3)?', '["\u2265 0.5 mm", "\u2265 1 mm", "\u2265 2 mm", "\u2265 5 mm"]', 1, 'The standard criteria for STEMI is ST elevation \u2265 1 mm in two or more contiguous leads.'),
    (v_topic_id, '103: In leads V2 and V3, the threshold for ST elevation is higher. For men \u2265 40 years old, what is the threshold for STEMI in these leads?', '["1 mm", "1.5 mm", "2 mm", "2.5 mm"]', 2, 'In V2-V3, the threshold is \u2265 2 mm in men \u2265 40, \u2265 2.5 mm in men < 40, and \u2265 1.5 mm in women.'),
    (v_topic_id, '104: Myocardial ischemia typically causes which ST-segment abnormality?', '["ST-segment elevation", "ST-segment depression (horizontal or downsloping)", "Upsloping ST-segment depression", "ST-segment elevation with a concave upwards shape"]', 1, 'Horizontal or downsloping ST-depression \u2265 0.5 mm is highly suggestive of subendocardial ischemia.'),
    (v_topic_id, '105: What constitutes a "Pathological Q-wave"?', '["Any Q-wave in Lead III", "A Q-wave > 0.04s wide or > 25% of the height of the following R-wave", "A Q-wave in Lead aVR", "A Q-wave < 1 mm deep"]', 1, 'Pathological Q-waves indicate transmural infarction and usually appear hours to days after the acute event.'),
    (v_topic_id, '106: ST-segment elevation in Leads II, III, and aVF localizes the MI to which wall of the heart?', '["Anterior", "Septal", "Lateral", "Inferior"]', 3, 'Leads II, III, and aVF are the inferior leads, looking at the diaphragmatic surface of the heart.'),
    (v_topic_id, '107: Inferior wall MI is most commonly caused by occlusion of which coronary artery?', '["Left Anterior Descending (LAD)", "Left Circumflex (LCx)", "Right Coronary Artery (RCA)", "Left Main"]', 2, 'In ~80% of patients, the RCA supplies the inferior wall (right-dominant circulation).'),
    (v_topic_id, '108: ST-segment elevation in Leads V1, V2, V3, and V4 localizes the MI to which wall?', '["Anterior", "Lateral", "Inferior", "Posterior"]', 0, 'V1-V4 are the anterior and septal leads.'),
    (v_topic_id, '109: Anterior wall MI is caused by occlusion of which coronary artery?', '["Right Coronary Artery", "Left Anterior Descending (LAD)", "Left Circumflex", "Diagonal branch"]', 1, 'The LAD supplies the anterior wall and the septum; its occlusion can lead to devastating pump failure.'),
    (v_topic_id, '110: ST-segment elevation in Leads I, aVL, V5, and V6 localizes the MI to which wall?', '["Anterior", "Lateral", "Septal", "Inferior"]', 1, 'These leads look at the lateral wall of the left ventricle.'),
    (v_topic_id, '111: Lateral wall MI is most commonly associated with occlusion of which artery?', '["Left Anterior Descending", "Left Circumflex (LCx) or diagonal branch of LAD", "Right Coronary Artery", "Right Marginal artery"]', 1, 'The LCx typically supplies the lateral wall.'),
    (v_topic_id, '112: "Wellens Syndrome" (Type B) is characterized by deep, symmetric T-wave inversions in V2 and V3. This is a critical finding because it indicates:', '["Acute pericarditis", "High-grade stenosis of the proximal LAD", "Right heart strain", "Normal variant in athletes"]', 1, 'Wellens syndrome is a pre-infarction state; these patients are at high risk for a massive anterior MI.'),
    (v_topic_id, '113: How does a "Posterior MI" typically present on a standard 12-lead ECG?', '["ST elevation in V1-V3", "ST depression and tall R-waves in V1-V3 (reciprocal changes)", "ST elevation in II, III, aVF", "Low voltage QRS"]', 1, 'Because V1-V3 are opposite to the posterior wall, they show reciprocal changes: ST depression, tall R-waves (instead of Q-waves), and upright T-waves.'),
    (v_topic_id, '114: To confirm a suspected Posterior MI, which additional leads should be placed on the patient''s back?', '["V1, V2, V3", "V4R, V5R, V6R", "V7, V8, V9", "V3R, V4R"]', 2, 'V7 (posterior axillary line), V8 (scapular line), and V9 (paraspinal line) look directly at the posterior wall.'),
    (v_topic_id, '115: About 40% of patients with an Inferior MI also have a Right Ventricular (RV) MI. Which lead is the most sensitive for detecting RV MI?', '["Lead V1", "Lead V4R (in a right-sided ECG)", "Lead aVR", "Lead III"]', 1, 'ST elevation in V4R (right 5th intercostal space, midclavicular line) is highly sensitive and specific for RV involvement.'),
    (v_topic_id, '116: Why is it clinically vital to identify an RV Infarction in a patient with an Inferior MI?', '["They require aggressive beta-blocker therapy", "They are extremely preload-dependent and can develop severe hypotension if given nitrates or morphine", "They always require a pacemaker", "They have a much better prognosis"]', 1, 'RV infarction impairs the heart''s ability to pump blood to the left side. Nitrates reduce preload and can cause a catastrophic drop in blood pressure.'),
    (v_topic_id, '117: ST-segment depression in Lead aVL is a very early and sensitive "reciprocal change" for which type of MI?', '["Anterior MI", "Inferior MI", "Lateral MI", "Septal MI"]', 1, 'ST depression in aVL is often the first sign of an acute inferior MI.'),
    (v_topic_id, '118: A new Left Bundle Branch Block (LBBB) in the setting of chest pain should be managed as:', '["A benign finding", "A STEMI equivalent (until proven otherwise)", "Stable angina", "Pericarditis"]', 1, 'A new LBBB obscures the ST segments, potentially hiding a STEMI. Current guidelines treat new LBBB with ischemic symptoms as a STEMI equivalent.'),
    (v_topic_id, '119: What are the "Sgarbossa Criteria" used for?', '["Diagnosing MI in the presence of LBBB", "Calculating heart rate in AFib", "Localizing an accessory pathway", "Diagnosing PE"]', 0, 'Sgarbossa criteria help identify acute MI in patients with pre-existing LBBB or a paced rhythm.'),
    (v_topic_id, '120: Which Sgarbossa criterion is the most specific for acute MI in LBBB?', '["Concordant ST elevation \u2265 1 mm in any lead", "Discordant ST elevation \u2265 5 mm", "ST depression in V1-V3", "T-wave inversion in Lead I"]', 0, 'ST elevation that is in the same direction as the QRS (concordant) is highly abnormal in LBBB and very specific for MI.'),
    (v_topic_id, '121: Acute Pericarditis is classically characterized by which ST-segment change?', '["Downsloping ST depression in lateral leads", "Diffuse, concave-upwards ST elevation with PR-segment depression", "Localized ST elevation with reciprocal changes", "Horizontal ST depression in V1-V3"]', 1, 'The ST elevation in pericarditis is usually diffuse (not following a vascular territory) and concave (like a "smiley face").'),
    (v_topic_id, '122: In Pericarditis, which lead often shows "reciprocal" ST depression and PR-segment elevation?', '["Lead aVR", "Lead II", "Lead V1", "Lead V6"]', 0, 'Lead aVR is the only lead that typically shows reciprocal changes to the diffuse findings of pericarditis.'),
    (v_topic_id, '123: "Benign Early Repolarization" (BER) is a common STEMI mimic. It is characterized by:', '["Concave ST elevation, most prominent in V2-V5, with a \"fishhook\" notch at the J-point", "Pathological Q-waves", "Reciprocal ST depression in inferior leads", "PR segment elevation in all leads"]', 0, 'BER is common in young, healthy individuals and is distinguished from STEMI by the lack of reciprocal changes and its stability over time.'),
    (v_topic_id, '124: "De Winter T-waves" consist of upsloping ST depression followed by tall, symmetric T-waves in the precordial leads. This signifies:', '["Normal response to exercise", "Acute proximal LAD occlusion", "Hyperkalemia", "Digitalis effect"]', 1, 'This is a STEMI equivalent indicating an acute LAD occlusion without classic ST elevation.'),
    (v_topic_id, '125: ST elevation in Lead aVR that is greater than ST elevation in Lead V1 is highly suggestive of:', '["Inferior MI", "Left Main Coronary Artery (LMCA) occlusion or triple vessel disease", "Right Ventricular Hypertrophy", "Pulmonary Embolism"]', 1, 'This is a high-risk finding indicating global subendocardial ischemia or severe multi-vessel disease.'),
    (v_topic_id, '126: "Brugada Syndrome" (Type 1) is a genetic channelopathy that can lead to sudden cardiac death. What is its hallmark ECG finding?', '["Short QT interval", "Coved ST elevation > 2 mm followed by a negative T-wave in V1-V2", "Delta waves in all leads", "Diffuse ST depression"]', 1, 'This "pseudo-RBBB" pattern in the right precordial leads is the classic Brugada sign.'),
    (v_topic_id, '127: A patient has ST elevation in II, III, and aVF. You also see ST elevation in V1 and V4R. Where is the infarction?', '["Inferior wall only", "Infero-lateral wall", "Inferior wall and Right Ventricle", "Anterior wall"]', 2, 'ST elevation in right-sided leads (V1, V4R) in the context of an inferior MI confirms RV involvement.'),
    (v_topic_id, '128: After an acute MI, how long does it typically take for T-wave inversion to occur?', '["Within minutes", "Hours to days", "Weeks", "Months"]', 1, 'T-wave inversion usually follows the ST-elevation phase as the infarct evolves.'),
    (v_topic_id, '129: Persistent ST-segment elevation weeks or months after an acute MI, especially in the anterior leads, suggests the development of a:', '["New acute MI", "Ventricular aneurysm", "Recurrent pericarditis", "Dressler syndrome"]', 1, 'A ventricular aneurysm is a scarred, non-contractile area of the myocardium that causes persistent ST elevation.'),
    (v_topic_id, '130: Which ECG leads look at the "High Lateral" wall of the heart?', '["I and aVL", "V5 and V6", "II and III", "V1 and V2"]', 0, 'Leads I and aVL are high lateral, while V5 and V6 are low lateral.'),
    (v_topic_id, '131: A 50-year-old male with severe chest pain has ST depression in V1-V3 and tall, upright T-waves. What is the most appropriate next step?', '["Discharge with reassurance", "Order a stress test", "Obtain posterior leads (V7-V9) to look for a Posterior STEMI", "Treat for a pulmonary embolism"]', 2, 'This pattern is highly suspicious for a posterior wall MI.'),
    (v_topic_id, '132: What is the significance of "convex" (domed) ST-segment elevation (the "tombstone" pattern)?', '["It is more likely to be benign", "It is highly suggestive of acute transmural infarction", "It is typical of pericarditis", "It indicates old scar tissue"]', 1, 'Convex ST elevation (coved) is more strongly associated with acute STEMI than concave elevation.'),
    (v_topic_id, '133: "Reciprocal changes" refer to:', '["ST elevation in one lead appearing as ST depression in the lead looking from the opposite direction", "The heart rate doubling", "T-waves becoming taller", "The PR interval lengthening"]', 0, 'Reciprocal ST depression is a highly specific indicator that ST elevation in the opposing leads is due to an acute STEMI rather than a mimic.'),
    (v_topic_id, '134: An Inferior MI with ST elevation in Lead III greater than Lead II is more likely to be caused by which artery?', '["Left Circumflex", "Right Coronary Artery (RCA)", "Left Anterior Descending", "Diagonal branch"]', 1, 'Lead III is more "right-sided" than Lead II; therefore, RCA occlusion typically produces more elevation in III than II.'),
    (v_topic_id, '135: An Inferior MI with ST elevation in Lead II greater than Lead III, or with ST elevation in I and aVL, is more likely to be:', '["Right Coronary Artery occlusion", "Left Circumflex (LCx) occlusion", "LAD occlusion", "Septal branch occlusion"]', 1, 'The LCx supplies the lateral and sometimes the inferior wall; elevation in I, aVL, or II > III suggests LCx.'),
    (v_topic_id, '136: A patient with a history of heart failure and a known old LBBB presents with stable, non-ischemic chest pain. Their ECG shows 2 mm of discordant ST elevation in V1-V3. Is this a STEMI?', '["Yes, absolutely", "No, this is a normal finding in LBBB", "Yes, any ST elevation in LBBB is a STEMI", "Only if there are reciprocal changes"]', 1, 'In LBBB, the ST segments are normally discordant (opposite) to the QRS. Up to 5 mm of discordant ST elevation can be a normal part of the LBBB pattern.'),
    (v_topic_id, '137: "T-wave pseudonormalization" refers to:', '["A T-wave that was previously inverted becoming upright during an episode of acute ischemia", "A T-wave that becomes very tall", "A T-wave that disappears", "A T-wave that follows a U-wave"]', 0, 'This is a subtle but important sign of acute ischemia in a patient who had baseline T-wave inversions.'),
    (v_topic_id, '138: "Biphasic T-waves" (initially positive then negative) in V2-V3 are characteristic of:', '["Brugada syndrome", "Wellens Syndrome (Type A)", "Hypokalemia", "Digitalis effect"]', 1, 'Wellens Type A (biphasic T-waves) and Type B (deep inversions) both indicate critical LAD stenosis.'),
    (v_topic_id, '139: Subendocardial infarction (NSTEMI) is typically manifested on the ECG as:', '["ST elevation", "Pathological Q-waves", "ST-segment depression or T-wave inversion without Q-waves", "Wide QRS complexes"]', 2, 'NSTEMIs do not involve the entire thickness of the wall, so they usually do not produce ST elevation or Q-waves.'),
    (v_topic_id, '140: A "non-Q-wave MI" is another term for:', '["STEMI", "NSTEMI", "Unstable Angina", "Pericarditis"]', 1, 'NSTEMIs generally do not develop pathological Q-waves.'),
    (v_topic_id, '141: What is the significance of a "Q-wave" in Lead aVR?', '["It indicates an old MI", "It is a normal finding in almost everyone", "It suggests dextrocardia", "It indicates an anterior MI"]', 1, 'Lead aVR is oriented toward the "empty" space of the right atrium and the top of the heart; Q-waves are expected there.'),
    (v_topic_id, '142: An isolated Q-wave in Lead III (without Q-waves in II or aVF) is often:', '["A sign of an old inferior MI", "A normal variant (especially if it disappears with deep inspiration)", "A sign of a posterior MI", "Diagnostic of pulmonary embolism"]', 1, 'Isolated Q-waves in Lead III are common and non-pathological if they are not seen in the other inferior leads.'),
    (v_topic_id, '143: A "Poor R-wave progression" is defined as an R-wave height less than ___ mm in Lead V3.', '["1 mm", "3 mm", "5 mm", "10 mm"]', 1, 'R-wave < 3 mm in V3 is the common threshold for PRWP.'),
    (v_topic_id, '144: "ST-segment depression" is measured at the J-point. For it to be considered clinically significant for ischemia, it should be at least:', '["0.5 mm in two contiguous leads", "1 mm in one lead only", "2 mm in all leads", "5 mm in limb leads"]', 0, 'The standard threshold for significant ischemia is \u2265 0.5 mm of horizontal or downsloping depression.'),
    (v_topic_id, '145: Which of the following can cause "ST elevation" besides an acute MI?', '["Hyperkalemia", "Brugada syndrome", "Left Ventricular Aneurysm", "All of the above"]', 3, 'There are many non-ischemic causes of ST elevation.'),
    (v_topic_id, '146: "Prinzmetal (Variant) Angina" is caused by coronary artery vasospasm. What does its ECG typically show during an episode of pain?', '["Persistent ST depression", "Transient ST-segment elevation that resolves when the pain subsides", "Pathological Q-waves", "LBBB"]', 1, 'The vasospasm causes transient transmural ischemia, manifesting as ST elevation that reverts to baseline after the spasm resolves.'),
    (v_topic_id, '147: Which lead provides the best view of the "Right Atrium"?', '["Lead I", "Lead V1", "Lead V6", "Lead aVL"]', 1, 'V1 is positioned directly over the right atrium/ventricle area.'),
    (v_topic_id, '148: A "J-wave" (Osborn wave) is a positive deflection at the J-point. It is the classic ECG finding in:', '["Hyperthermia", "Hypothermia", "Hypercalcemia", "Hypokalemia"]', 1, 'Osborn waves are highly characteristic of severe hypothermia (< 32\u00b0C).'),
    (v_topic_id, '149: "Digitalis effect" (not toxicity) is characterized by:', '["Tall T-waves", "Scooped (sagging) ST-segment depression", "ST elevation in V1", "Shortened PR interval"]', 1, 'The "Salvador Dali mustache" sag of the ST segment is a normal finding in patients taking Digoxin.'),
    (v_topic_id, '150: Which heart rhythm is a common sign of "Digitalis Toxicity"?', '["Sinus Tachycardia", "Paroxysmal Atrial Tachycardia with AV block", "Atrial Fibrillation with a fast ventricular rate", "RBBB"]', 1, 'Digoxin increases atrial excitability but slows AV conduction, leading to this classic "tachy-block" combination.'),
    (v_topic_id, '151: "Takotsubo Cardiomyopathy" (Broken Heart Syndrome) mimics a STEMI. What is its hallmark finding on echocardiography?', '["Basal wall motion abnormalities", "Apical ballooning of the left ventricle", "Right ventricular dilation", "Pericardial effusion"]', 1, 'The ECG often shows ST elevation in the anterior leads, but angiography shows clean coronary arteries and apical ballooning.'),
    (v_topic_id, '152: ST-segment elevation in Leads V1 and aVR, accompanied by diffuse ST depression in most other leads, is highly suggestive of:', '["Inferior MI", "Left Main or proximal LAD occlusion", "Pericarditis", "Normal variant"]', 1, 'Elevation in aVR with widespread depression indicates severe subendocardial ischemia, often from the Left Main artery.'),
    (v_topic_id, '153: A patient has ST elevation in V1-V6, I, and aVL. This describes an:', '["Anteroseptal MI", "Extensive Anterior MI", "Infero-lateral MI", "Posterior MI"]', 1, 'This is a large infarction involving the entire anterior and lateral walls of the LV.'),
    (v_topic_id, '154: The "LAD" artery usually bifurcates into which two main branches?', '["Right Marginal and PDA", "Septal and Diagonal branches", "Obtuse Marginal and SA nodal branches", "Circumflex and Marginal"]', 1, 'The LAD gives off septal branches to the septum and diagonal branches to the anterior/lateral wall.'),
    (v_topic_id, '155: Occlusion of a "Diagonal branch" of the LAD would likely cause ST elevation in which leads?', '["V1 and V2", "II, III, aVF", "I, aVL, and possibly V5-V6", "aVR only"]', 2, 'Diagonal branches supply the lateral wall of the left ventricle.'),
    (v_topic_id, '156: Occlusion of the "Septal branch" of the LAD would cause ST elevation in:', '["V1 and V2", "V5 and V6", "Lead I", "aVF"]', 0, 'V1 and V2 are the septal leads.'),
    (v_topic_id, '157: A "hyperacute" T-wave is distinguished from a "hyperkalemic" T-wave because the former is:', '["Narrow and peaked", "Broad-based and symmetric", "Inverted", "Asymmetric"]', 1, 'Ischemic T-waves are broad-based, while hyperkalemic T-waves are characteristically "tented" or narrow-based and very sharp.'),
    (v_topic_id, '158: "ST-segment depression" that is only seen during an exercise stress test and resolves during rest indicates:', '["Myocardial infarction", "Reversible myocardial ischemia (Angina)", "Old scar tissue", "Normal response to exercise"]', 1, 'Inducible ST depression is the hallmark of stable coronary artery disease.'),
    (v_topic_id, '159: Which condition is associated with a "shortened QT interval"?', '["Hypocalcemia", "Hypercalcemia", "Hypokalemia", "Hypomagnesemia"]', 1, 'Hypercalcemia shortens the ST segment and the overall QT interval. Hypocalcemia prolongs it.'),
    (v_topic_id, '160: A patient has "S1Q3T3" pattern (S in I, Q in III, T-inversion in III). This is a classic but relatively insensitive sign for:', '["Myocardial Infarction", "Pulmonary Embolism (Acute Cor Pulmonale)", "Left Bundle Branch Block", "Aortic Dissection"]', 1, 'S1Q3T3 indicates acute right heart strain.'),
    (v_topic_id, '161: What is the most common ECG finding in a patient with a Pulmonary Embolism?', '["S1Q3T3", "RBBB", "Sinus Tachycardia", "Atrial Fibrillation"]', 2, 'While S1Q3T3 is classic, simple sinus tachycardia is the most common finding.'),
    (v_topic_id, '162: "Inverted T-waves" in leads V1, V2, and V3 in an adult can be a sign of:', '["Right heart strain (e.g., PE or Pulmonary Hypertension)", "Left Ventricular Hypertrophy", "Lateral MI", "Normal finding in everyone"]', 0, 'T-wave inversions in the right precordial leads are a sign of RV strain.'),
    (v_topic_id, '163: A "Giant negative T-wave" (> 10 mm) in the precordial leads is a characteristic finding in which condition?', '["Apical Hypertrophic Cardiomyopathy (Yamaguchi Syndrome)", "Anterior MI", "Hypokalemia", "Hypothermia"]', 0, 'This is a rare but classic variant of HCM.'),
    (v_topic_id, '164: In a patient with "Acute Pericarditis", the ST-segment usually returns to baseline before the _____ becomes inverted.', '["P-wave", "QRS complex", "T-wave", "U-wave"]', 2, 'The progression of pericarditis involves ST elevation, then normalization, then T-wave inversion.'),
    (v_topic_id, '165: A "U-wave" that is inverted is almost always:', '["Normal", "Pathological (indicating ischemia or LV overload)", "A sign of hypercalcemia", "A sign of hyperthyroidism"]', 1, 'While upright U-waves can be normal or due to hypokalemia, inverted U-waves are highly specific for heart disease.'),
    (v_topic_id, '166: Which of the following leads is considered "Bipolar"?', '["aVR", "V1", "Lead I", "aVL"]', 2, 'Leads I, II, and III are bipolar; the augmented limb leads and precordial leads are unipolar.'),
    (v_topic_id, '167: If the QRS complex is negative in Lead II and positive in Lead I, the axis is:', '["Normal", "Left Axis Deviation", "Right Axis Deviation", "Extreme Deviation"]', 1, 'In the "two-lead" method, if I is positive and II is negative, the axis is definitely LAD.'),
    (v_topic_id, '168: If the QRS complex is isoelectric in Lead II, what is the heart''s electrical axis?', '["0 degrees", " +90 degrees", "-30 degrees", "+150 degrees"]', 2, 'The axis is perpendicular to the isoelectric lead. Perpendicular to Lead II (+60) is -30 (or +150, but usually -30).'),
    (v_topic_id, '169: "Lown-Ganong-Levine" syndrome is characterized by:', '["Short PR interval with a normal QRS complex", "Delta waves", "Prolonged QT interval", "Delta waves and narrow QRS"]', 0, 'LGL is another pre-excitation syndrome but lacks the delta wave of WPW.'),
    (v_topic_id, '170: "Brugada Type 2" is distinguished by which T-wave morphology?', '["Deeply inverted T-wave", "Saddle-back ST elevation followed by an upright or biphasic T-wave", "Biphasic T-wave", "Flat T-wave"]', 1, 'Type 1 is "coved," while Type 2 is "saddle-back."'),
    (v_topic_id, '171: "Early Repolarization" is most commonly seen in which leads?', '["II, III, aVF", "V2 through V5", "I and aVL", "aVR and V1"]', 1, 'It is usually most prominent in the mid-to-lateral precordial leads.'),
    (v_topic_id, '172: Which lead is used as the "ground" in a standard ECG setup?', '["Right Arm", "Left Arm", "Left Leg", "Right Leg"]', 3, 'The right leg electrode is the reference ground.'),
    (v_topic_id, '173: "Clockwise rotation" of the heart on ECG is characterized by:', '["Early R-wave progression (Transition at V1/V2)", "Delayed R-wave progression (Transition at V5/V6)", "Left Axis Deviation", "Tall P-waves"]', 1, 'Transition refers to where the QRS becomes more positive than negative. Late transition is "clockwise" rotation.'),
    (v_topic_id, '174: "Counter-clockwise rotation" of the heart is characterized by:', '["Early R-wave progression (Transition at V1/V2)", "Late R-wave progression", "Right Axis Deviation", "Shortened PR interval"]', 0, 'Early transition is "counter-clockwise" rotation.'),
    (v_topic_id, '175: A "Low-amplitude QRS" in a patient with COPD is primarily due to:', '["Small heart", "Increased air in the lungs insulating the electrical signal", "Left Ventricular Hypertrophy", "Hypokalemia"]', 1, 'Air is a poor conductor; hyperinflated lungs in COPD dampen the surface ECG signal.'),
    (v_topic_id, '176: In Lead II, the right arm electrode is _____ and the left leg electrode is _____.', '["Negative, Positive", "Positive, Negative", "Negative, Neutral", "Positive, Positive"]', 0, 'Lead II measures from RA (-) to LL (+).'),
    (v_topic_id, '177: In Lead III, the left arm electrode is _____ and the left leg electrode is _____.', '["Negative, Positive", "Positive, Negative", "Negative, Neutral", "Positive, Positive"]', 0, 'Lead III measures from LA (-) to LL (+).'),
    (v_topic_id, '178: "Wilson''s Central Terminal" is a reference point created by averaging the potentials of:', '["V1, V2, V3", "RA, LA, and LL", "Lead I and Lead II", "V4, V5, V6"]', 1, 'This serves as the virtual "center" of the heart for unipolar lead measurements.'),
    (v_topic_id, '179: A "Wandering baseline" on an ECG is usually an artifact caused by:', '["Patient movement or poor electrode contact", "A dying heart", "AC interference", "Muscle tremors"]', 0, 'Respiratory movement or loose leads causes the baseline to "drift."'),
    (v_topic_id, '180: "60-cycle interference" (AC interference) appears on the ECG as:', '["A thick, fuzzy baseline", "Large, irregular spikes", "A drifting baseline", "Tall, peaked T-waves"]', 0, 'Electrical noise from nearby equipment or wires creates a regular, high-frequency "fuzz" on the strip.'),
    (v_topic_id, '181: If the "Left Arm" and "Right Arm" electrodes are reversed, what will Lead I look like?', '["Normal", "Completely inverted (negative P, QRS, and T)", "It will be a flat line", "It will look like Lead III"]', 1, 'Lead I measures RA to LA; reversing them flips the lead upside down.'),
    (v_topic_id, '182: Lead V1 is placed at the:', '["4th intercostal space, right sternal border", "4th intercostal space, left sternal border", "5th intercostal space, midclavicular line", "Left axillary line"]', 0, 'This is the standard position for V1.'),
    (v_topic_id, '183: Lead V2 is placed at the:', '["4th intercostal space, left sternal border", "4th intercostal space, right sternal border", "5th intercostal space, midclavicular line", "Left sternal border, 2nd intercostal space"]', 0, 'This is the standard position for V2.'),
    (v_topic_id, '184: Lead V4 is placed at the:', '["4th intercostal space, midclavicular line", "5th intercostal space, midclavicular line", "6th intercostal space, midaxillary line", "Between V2 and V3"]', 1, 'V4 is placed at the apex of the heart.'),
    (v_topic_id, '185: Lead V6 is placed at the:', '["5th intercostal space, midaxillary line", "5th intercostal space, anterior axillary line", "4th intercostal space, midaxillary line", "Left sternal border"]', 0, 'V6 is the most lateral precordial lead.'),
    (v_topic_id, '186: "ST elevation" that follows a "convex" or straight line from the J-point to the T-wave is:', '["Benign", "More likely to be an acute STEMI", "Typical of pericarditis", "Always due to a bundle branch block"]', 1, 'Convexity is a "red flag" for acute transmural ischemia.'),
    (v_topic_id, '187: A "hyperacute" T-wave often has a width at its base that is _____ than the preceding QRS complex.', '["Narrower", "Wider", "The same", "Zero"]', 1, 'Broad-based symmetry is a key feature of hyperacute ischemic T-waves.'),
    (v_topic_id, '188: A pathological Q-wave must be at least how deep to be considered significant?', '["0.5 mm", "1 mm", "More than 25% of the total R-wave amplitude in that lead", "5 mm"]', 2, 'This relative depth criteria is standard.'),
    (v_topic_id, '189: "Reciprocal ST depression" in Leads II, III, and aVF is commonly seen in which type of MI?', '["Inferior MI", "High Lateral or Anterior MI", "Posterior MI", "Right Ventricular MI"]', 1, 'Inferior leads show reciprocal depression for superior/lateral elevation.'),
    (v_topic_id, '190: "Reciprocal ST depression" in Leads V1-V3 is commonly seen in which type of MI?', '["Anterior MI", "Inferior MI", "Posterior MI", "Septal MI"]', 2, 'V1-V3 are the reciprocal leads for the posterior wall.'),
    (v_topic_id, '191: "Reciprocal ST depression" in Lead I and aVL is commonly seen in which type of MI?', '["Inferior MI", "Anterior MI", "Septal MI", "Lateral MI"]', 0, 'Inferior MI (II, III, aVF elevation) often shows depression in I and aVL.'),
    (v_topic_id, '192: A "ventricular rate" of 150 bpm in a patient with a "sawtooth" baseline suggests:', '["Atrial Fibrillation", "Atrial Flutter with 2:1 conduction", "Atrial Flutter with 4:1 conduction", "Sinus Tachycardia"]', 1, 'Since the flutter rate is usually 300, 2:1 conduction results in a ventricular rate of 150.'),
    (v_topic_id, '193: "Biventricular Hypertrophy" on ECG may show:', '["Voltage criteria for both LVH and RVH", "Normal voltage due to cancellation of electrical forces", "Both A and B are possible", "Only RAD"]', 2, 'Sometimes the forces cancel out, making the ECG look surprisingly normal despite dual hypertrophy.'),
    (v_topic_id, '194: "Right Atrial Enlargement" is often associated with which chronic medical condition?', '["Mitral Stenosis", "Chronic Obstructive Pulmonary Disease (COPD)", "Systemic Hypertension", "Aortic Stenosis"]', 1, 'Chronic lung disease causes pulmonary hypertension, which leads to RAE and RVH.'),
    (v_topic_id, '195: "Left Atrial Enlargement" is often associated with which valvular heart disease?', '["Aortic Insufficiency", "Mitral Stenosis", "Pulmonic Stenosis", "Tricuspid Regurgitation"]', 1, 'Stenosis of the mitral valve increases pressure in the left atrium, causing it to enlarge.'),
    (v_topic_id, '196: The "interatrial conduction time" is represented by the:', '["P-wave duration", "PR interval", "QRS duration", "ST segment"]', 0, 'The width of the P-wave reflects how long it takes for the impulse to spread across both atria.'),
    (v_topic_id, '197: "Intraventricular conduction delay" (IVCD) is a term used when the QRS is wide (> 0.12s) but:', '["The PR interval is short", "The pattern does not clearly fit RBBB or LBBB", "There is a delta wave", "The axis is normal"]', 1, 'IVCD is a "catch-all" term for non-specific widening.'),
    (v_topic_id, '198: A "P-wave" that is negative in Lead II, III, and aVF suggests that the pacemaker is:', '["In the SA node", "In the AV junction or low atrium (retrograde conduction)", "In the ventricles", "In the left bundle branch"]', 1, 'Retrograde conduction from a low pacemaker point causes the atria to depolarize from bottom-to-top, resulting in inverted P-waves in the inferior leads.'),
    (v_topic_id, '199: A "hidden P-wave" (buried within the QRS) is a common finding in:', '["Sinus Bradycardia", "AV Nodal Re-entrant Tachycardia (AVNRT)", "Atrial Flutter", "First-degree AV block"]', 1, 'In common AVNRT, the atria and ventricles are depolarized almost simultaneously.'),
    (v_topic_id, '200: "ST-segment elevation" that persists for more than 2 weeks after an acute MI should raise suspicion for:', '["Re-infarction", "Ventricular aneurysm", "Pericarditis", "Dressler syndrome"]', 1, 'A ventricular aneurysm is the most common cause of persistent ST elevation post-MI.');
